+import static org.mockito.Mockito.*;
+
+class UC002ViewVeterinariansTest extends PetClinicTestBase {
+    @Autowired
+    private DSLContext dsl;
+
+    @MockitoSpyBean
+    private VetRepository repository;
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = {"BR-002", "BR-003"})
+    void menuOpensDirectoryWithNamesAndOrderedSpecialtiesAnonymously() {
+        navigate(WelcomeView.class);
+        SideNavItem link = assertDoesNotThrow(() -> find(SideNavItem.class)
+                .withPropertyValue(SideNavItem::getLabel, "Veterinarians").single(),
+                "Veterinarians navigation should exist");
+        UI.getCurrent().navigate(link.getPath());
+        Grid<Vet> grid = grid();
+        assertEquals(6, test(grid).size());
+        assertEquals(List.of("First name", "Last name", "Specialties"),
+                grid.getColumns().stream().map(Grid.Column::getHeaderText).toList());
+        assertEquals("James", test(grid).getCellText(0, 0));
+        assertEquals("Carter", test(grid).getCellText(0, 1));
+        assertEquals("none", test(grid).getCellText(0, 2));
+        assertEquals("Linda", test(grid).getCellText(1, 0));
+        assertEquals("dentistry, surgery", test(grid).getCellText(1, 2));
+        assertEquals("Helen", test(grid).getCellText(3, 0));
+        assertEquals("radiology", test(grid).getCellText(3, 2));
+        assertEquals(6, dsl.fetchCount(VETS));
+    }
+
+    @Test
+    @UseCase(id = "UC-002", scenario = "A1: No Veterinarians Registered")
+    void emptyDirectoryKeepsGridWithoutRows() {
+        dsl.deleteFrom(VET_SPECIALTIES).execute();
+        dsl.deleteFrom(VETS).execute();
+        navigate(VetsView.class);
+        assertEquals(0, test(grid()).size());
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-001")
+    void gridFetchesBoundedNonOverlappingPagesUntilExhausted() {
+        for (int i = 0; i < 123; i++) {
+            dsl.insertInto(VETS, VETS.FIRST_NAME, VETS.LAST_NAME)
+                    .values("Additional", "Vet%03d".formatted(i)).execute();
+        }
+        navigate(VetsView.class);
+        Grid<Vet> grid = grid();
+        assertFalse(grid.getDataProvider().isInMemory());
+        assertEquals(129, grid.getDataProvider().size(new Query<>()));
+        clearInvocations(repository);
+        List<Vet> first = page(grid, 0, 50);
+        List<Vet> second = page(grid, 50, 50);
+        List<Vet> last = page(grid, 100, 50);
+        assertEquals(50, first.size());
+        assertEquals(50, second.size());
+        assertEquals(29, last.size());
+        assertEquals(129, java.util.stream.Stream.of(first, second, last)
+                .flatMap(List::stream).map(Vet::id).distinct().count());
+        assertTrue(page(grid, 129, 50).isEmpty());
+        verify(repository).findPage(0, 50);
+        verify(repository).findPage(50, 50);
+        verify(repository).findPage(100, 50);
+        verify(repository).findPage(129, 50);
+        verifyNoMoreInteractions(repository);
+    }
+
+    @Test
+    @UseCase(id = "UC-002")
+    void countFailureShowsApplicationErrorWithoutGrid() {
+        navigate(VetsView.class);
+        Grid<Vet> grid = grid();
+        doThrow(new DataAccessResourceFailureException("Directory unavailable"))
+                .when(repository).count();
+        grid.getDataProvider().size(new Query<>());
+        assertErrorView();
+    }
+
+    @Test
+    @UseCase(id = "UC-002")
+    void laterPageFailureReplacesDirectoryWithApplicationError() {
+        navigate(VetsView.class);
+        Grid<Vet> grid = grid();
+        assertFalse(page(grid, 0, 2).isEmpty());
+        doThrow(new DataAccessResourceFailureException("Directory unavailable"))
+                .when(repository).findPage(2, 2);
+        page(grid, 2, 2);
+        assertErrorView();
+    }
+
+    private void assertErrorView() {
+        assertDoesNotThrow(() -> find(ApplicationErrorView.class).single(),
+                "Data access errors should render the application error view");
+        assertTrue(find(Grid.class).all().isEmpty(), "No veterinarian grid should remain");
+    }
+
+    private List<Vet> page(Grid<Vet> grid, int offset, int limit) {
+        return grid.getDataProvider().fetch(new Query<>(offset, limit, List.of(), null, null)).toList();
+    }
+
+    @SuppressWarnings("unchecked")
+    private Grid<Vet> grid() {
+        return assertDoesNotThrow(() -> find(Grid.class).single(), "Veterinarians grid should exist");
+    }
+}
